-- Migration: Year 4 - Ethics, Law & Health Systems (PART 1: 1-50)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — Medicare Part A & B

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- Master Wipe for this topic to ensure zero redundancy (Standalone MCQs only)
    -- Note: This only wipes standalone MCQs, not case-linked questions
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- MEDICARE ELIGIBILITY & BASICS
    (v_topic_id, 'To be eligible for Medicare at age 65, an individual who is not a US citizen must have been a permanent legal resident for at least how many consecutive years?', '["1 year", "3 years", "5 years", "10 years"]', 2, 'Non-citizens must be permanent legal residents for at least 5 continuous years to qualify for Medicare at age 65.'),
    (v_topic_id, 'How many "quarters of coverage" (credits earned through payroll taxes) are required for an individual to receive Medicare Part A without paying a monthly premium?', '["20 quarters", "30 quarters", "40 quarters", "50 quarters"]', 2, 'Individuals with 40 or more quarters of Medicare-covered employment are eligible for premium-free Part A. This is equivalent to 10 years of work.'),
    (v_topic_id, 'A 65-year-old male who has only 30 quarters of coverage wants to enroll in Medicare Part A. Which of the following is true regarding his enrollment?', '["He is ineligible for Part A", "He receives Part A for free", "He must pay a monthly premium for Part A", "He is automatically enrolled in Medicaid instead"]', 2, 'Individuals with 30-39 quarters of coverage can buy Part A by paying a monthly premium (which is lower than for those with <30 quarters).'),
    (v_topic_id, 'Which of the following conditions allows an individual under the age of 65 to qualify for Medicare without a 24-month waiting period after receiving disability benefits?', '["End-Stage Renal Disease (ESRD)", "Multiple Sclerosis (MS)", "Congestive Heart Failure (CHF)", "Parkinson Disease"]', 0, 'Individuals with ESRD or Amyotrophic Lateral Sclerosis (ALS) qualify for Medicare without the standard 24-month SSDI waiting period.'),
    (v_topic_id, 'For a patient receiving Social Security Disability Insurance (SSDI) for a chronic back injury, how many months must pass before they become eligible for Medicare?', '["6 months", "12 months", "24 months", "36 months"]', 2, 'Most individuals under 65 qualify for Medicare only after receiving SSDI for 24 months.'),

    -- MEDICARE PART A: HOSPITAL INSURANCE
    (v_topic_id, 'Medicare Part A is primarily funded by which of the following?', '["General federal tax revenue", "A dedicated payroll tax (FICA)", "Monthly premiums paid by all beneficiaries", "State government matching funds"]', 1, 'Part A is primarily funded by the Hospital Insurance (HI) Trust Fund, which is financed through a dedicated 2.9% payroll tax (shared by employees and employers).'),
    (v_topic_id, 'A "benefit period" in Medicare Part A begins the day a patient is admitted as an inpatient and ends when the patient has gone how many consecutive days without inpatient hospital or skilled nursing care?', '["30 days", "60 days", "90 days", "180 days"]', 1, 'A benefit period ends when a beneficiary has not received any inpatient hospital or SNF care for 60 days in a row.'),
    (v_topic_id, 'Under Medicare Part A, for each benefit period, how many days of inpatient hospital care are covered before the patient must begin using "lifetime reserve days"?', '["30 days", "60 days", "90 days", "100 days"]', 2, 'Medicare Part A covers up to 90 days of inpatient hospital care per benefit period. Beyond 90 days, patients use their non-renewable "lifetime reserve days."'),
    (v_topic_id, 'How many "lifetime reserve days" does Medicare Part A provide to each beneficiary over their lifetime?', '["30 days", "60 days", "90 days", "Unlimited"]', 1, 'Medicare provides 60 lifetime reserve days that can be used if a hospital stay exceeds 90 days in a single benefit period. These days are non-renewable.'),
    (v_topic_id, 'During the first 60 days of an inpatient hospital stay in a benefit period, what is the patient''s primary cost-sharing responsibility under Medicare Part A?', '["20% coinsurance", "A daily copayment", "A one-time deductible for the benefit period", "Full cost of medications"]', 2, 'For days 1-60, the patient only pays the Part A deductible for that benefit period. There is no daily coinsurance until day 61.'),
    (v_topic_id, 'From day 61 to day 90 of an inpatient hospital stay, what is the patient required to pay under Medicare Part A?', '["Nothing", "A daily coinsurance amount", "The full cost of the room", "20% of the total bill"]', 1, 'For days 61-90, the patient pays a daily coinsurance amount ($408 in 2024).'),

    -- MEDICARE PART A: SKILLED NURSING FACILITY (SNF)
    (v_topic_id, 'To qualify for Medicare Part A coverage of Skilled Nursing Facility (SNF) care, a patient must have a "qualifying hospital stay" of at least how many midnights?', '["1 midnight", "2 midnights", "3 midnights", "5 midnights"]', 2, 'A "qualifying stay" for SNF coverage requires at least 3 consecutive days (3 midnights) as a hospital inpatient.'),
    (v_topic_id, 'Which of the following status designations in the hospital would PREVENT a patient from qualifying for Medicare SNF coverage, even if they stay for 4 days?', '["Inpatient", "Observation status", "Critical Care", "Surgical recovery"]', 1, 'Time spent in "observation status" does not count toward the 3-day inpatient requirement for SNF coverage.'),
    (v_topic_id, 'Medicare Part A covers up to how many days of Skilled Nursing Facility (SNF) care per benefit period?', '["20 days", "50 days", "100 days", "Unlimited"]', 2, 'Medicare covers up to 100 days of SNF care per benefit period if the patient requires daily skilled nursing or rehab services.'),
    (v_topic_id, 'For the first 20 days of a covered SNF stay, how much coinsurance does the patient pay under Medicare Part A?', '["$0", "20%", "A fixed daily copay", "The Part A deductible"]', 0, 'Medicare Part A covers the first 20 days of a SNF stay in full ($0 coinsurance for the patient).'),
    (v_topic_id, 'For days 21 through 100 of a SNF stay, the patient is responsible for:', '["20% of the cost", "A daily coinsurance amount", "The full cost", "Nothing if they have Part B"]', 1, 'For days 21-100, the patient pays a daily coinsurance amount ($204 in 2024). After day 100, the patient pays all costs.'),

    -- MEDICARE PART A: HOSPICE & HOME HEALTH
    (v_topic_id, 'Which of the following is a requirement for a Medicare beneficiary to elect the hospice benefit?', '["They must be over age 75", "Two physicians must certify a life expectancy of 6 months or less", "They must have no family to care for them", "They must have already used all hospital days"]', 1, 'Hospice eligibility requires certification by both the attending physician and the hospice medical director that the patient is terminally ill with a life expectancy of 6 months or less.'),
    (v_topic_id, 'When a patient elects the Medicare hospice benefit, they waive their right to which of the following?', '["Pain management", "Doctor visits", "Curative treatment for the terminal illness", "Spiritual counseling"]', 2, 'Hospice enrollees agree to forego curative treatment for their terminal condition, though they can still receive treatment for unrelated conditions.'),
    (v_topic_id, 'Does Medicare Part A charge a deductible for hospice care?', '["Yes, the same as the hospital deductible", "No", "Only if the patient stays > 30 days", "Yes, but it is waived for cancer patients"]', 1, 'Medicare hospice care has no deductible and only minimal copayments for outpatient drugs and respite care.'),
    (v_topic_id, 'Under Medicare Part A, home health care is covered only if the patient is "homebound." Which of the following best defines "homebound" for Medicare purposes?', '["The patient never leaves the house", "Leaving the house requires a taxing effort and usually requires assistance", "The patient does not have a car", "The patient lives in a rural area"]', 1, 'Homebound means leaving the home is difficult, requires a taxing effort, and the patient needs help (from a person or device) to leave.'),

    -- MEDICARE PART B: MEDICAL INSURANCE
    (v_topic_id, 'Medicare Part B is primarily funded by which of the following?', '["Payroll taxes only", "General federal revenue and monthly premiums", "State inheritance taxes", "Corporate tax surcharges"]', 1, 'Unlike Part A, Part B is funded by a combination of general federal revenue (approx. 75%) and monthly premiums paid by enrollees (approx. 25%).'),
    (v_topic_id, 'Enrolling in Medicare Part B is generally:', '["Mandatory for all US citizens", "Automatic and free for everyone", "Voluntary and requires a monthly premium", "Only available to those who work > 40 hours/week"]', 2, 'Part B is voluntary and requires a monthly premium, though most people sign up as soon as they are eligible to avoid penalties.'),
    (v_topic_id, 'After the annual deductible is met, what is the standard coinsurance percentage that a patient pays for most Part B services (e.g., doctor visits)?', '["10%", "20%", "30%", "50%"]', 1, 'Medicare Part B typically pays 80% of the Medicare-approved amount, leaving the patient with a 20% coinsurance.'),
    (v_topic_id, 'Which of the following is NOT typically covered by Medicare Part B?', '["Outpatient surgery", "Clinical laboratory tests", "Routine dental exams and cleanings", "Durable medical equipment"]', 2, 'Original Medicare (Part A and B) generally does not cover routine dental, vision, or hearing services.'),
    (v_topic_id, 'Medicare Part B covers "Durable Medical Equipment" (DME). Which of the following is an example of DME?', '["Hospital beds for home use", "Disposable adult diapers", "Alcohol swabs", "Elastic bandages"]', 0, 'DME must be able to withstand repeated use (last 3+ years), be used for a medical reason, and be used in the home. Hospital beds, walkers, and oxygen equipment are examples.'),

    -- PREVENTIVE SERVICES
    (v_topic_id, 'The "Initial Preventive Physical Examination" (IPPE), also known as the "Welcome to Medicare" visit, must be performed within how many months of the patient''s first Part B enrollment?', '["3 months", "6 months", "12 months", "24 months"]', 2, 'The IPPE is a one-time benefit available only during the first 12 months of Part B enrollment.'),
    (v_topic_id, 'Following the initial year, Medicare Part B covers an "Annual Wellness Visit" (AWV) once every:', '["6 months", "12 months", "24 months", "Only if the patient gets sick"]', 1, 'The AWV is covered once every 12 months.'),
    (v_topic_id, 'For most recommended preventive services (e.g., flu shots, mammograms) that receive a Grade A or B from the USPSTF, what does the patient pay under Medicare Part B?', '["20% coinsurance", "The full deductible", "$0 (Coinsurance and deductible are waived)", "A $20 copay"]', 2, 'The Affordable Care Act mandated that Medicare Part B cover many preventive services at 100% (no cost-sharing for the patient) if the provider accepts assignment.'),
    (v_topic_id, 'Which of the following cancer screenings is covered by Medicare Part B for all beneficiaries of appropriate age?', '["Annual full-body skin check", "Annual screening mammogram for women over 40", "Annual PSA test for all men over 40", "Routine whole-body CT scans"]', 1, 'Medicare covers annual screening mammograms for women 40+. PSA tests are covered annually for men 50+, but with coinsurance/deductible applying unlike mammograms which are $0.'),
    (v_topic_id, 'How often does Medicare Part B cover a screening colonoscopy for an individual at "average risk" for colorectal cancer?', '["Every 2 years", "Every 5 years", "Every 10 years (or 4 years after a flex-sig)", "Once in a lifetime"]', 2, 'For average risk patients, a screening colonoscopy is covered every 120 months (10 years).'),

    -- ESRD & ALS SPECIAL RULES
    (v_topic_id, 'A 45-year-old patient is diagnosed with End-Stage Renal Disease (ESRD) and begins in-center hemodialysis. When does their Medicare coverage typically begin?', '["Immediately on the first day of dialysis", "The first day of the fourth month of dialysis", "After 1 year of dialysis", "Only if they have a transplant"]', 1, 'For in-center dialysis, there is a 3-month waiting period; coverage starts on the first day of the fourth month.'),
    (v_topic_id, 'Which of the following scenarios allows a patient with ESRD to bypass the 3-month waiting period for Medicare coverage?', '["If they are over age 50", "If they participate in a home dialysis training program", "If they are hospitalized for an infection", "There is no way to bypass it"]', 1, 'The waiting period is waived if the patient participates in a self-dialysis (home dialysis) training program before the end of the third month.'),
    (v_topic_id, 'If a patient under 65 is eligible for Medicare solely due to ESRD and receives a successful kidney transplant, how long will their Medicare coverage continue post-transplant?', '["12 months", "36 months", "Permanently", "Until they return to work"]', 1, 'Medicare coverage based on ESRD ends 36 months after a successful kidney transplant (unless they qualify by age or other disability).'),
    (v_topic_id, 'Which part of Medicare covers the actual dialysis treatments for a patient in an outpatient facility?', '["Part A", "Part B", "Part D", "Medigap"]', 1, 'Outpatient dialysis and related drugs/supplies are covered under Part B.'),

    -- MEDIGAP & SECONDARY INSURANCE
    (v_topic_id, 'What is "Medigap" (Medicare Supplement Insurance)?', '["Insurance for people who don''t qualify for Medicare", "Private insurance that covers "gaps" like deductibles and coinsurance in Original Medicare", "A government program for low-income seniors", "Insurance that replaces Medicare Part B"]', 1, 'Medigap is private insurance designed to supplement Original Medicare (A and B) by paying the patient''s share of costs.'),
    (v_topic_id, 'Can a patient who is enrolled in a "Medicare Advantage" (Part C) plan also purchase a Medigap policy?', '["Yes", "No, it is illegal for someone to sell them a Medigap policy", "Only if they have cancer", "Only if the Advantage plan is an HMO"]', 1, 'Medigap policies only work with Original Medicare. It is illegal for anyone to sell a Medigap policy to a person who has a Medicare Advantage plan.'),
    (v_topic_id, 'If a 66-year-old is still working at a company with 100 employees and has employer-sponsored insurance (ESI), which insurance is typically the "primary payer"?', '["Medicare", "The ESI plan", "They split 50/50", "Whichever the patient chooses first"]', 1, 'For individuals 65+ in a "large group health plan" (20+ employees), the ESI is the primary payer and Medicare is secondary.'),
    (v_topic_id, 'If a patient has "COBRA" coverage and turns 65, which insurance should be the primary payer?', '["COBRA", "Medicare", "Medicaid", "Social Security"]', 1, 'Medicare is almost always primary to COBRA for individuals aged 65+. Failure to enroll in Medicare when COBRA is active can lead to significant coverage gaps and penalties.'),

    -- BILLING & REIMBURSEMENT BASICS
    (v_topic_id, 'What does it mean when a physician "accepts assignment" from Medicare?', '["They agree to the Medicare-approved amount as full payment", "They charge the patient whatever they want", "They only see Medicare patients", "They are employed by the government"]', 0, 'Accepting assignment means the doctor agrees to accept the Medicare-approved amount (e.g., $100) as total payment; the patient only pays the 20% coinsurance ($20).'),
    (v_topic_id, 'What is a "Limiting Charge" in Medicare?', '["The maximum a doctor can charge if they do NOT accept assignment", "The maximum number of patients a doctor can see", "The amount Medicare pays for a surgery", "The annual out-of-pocket cap for Part B"]', 0, 'For "non-participating" providers who don''t accept assignment, federal law limits them to charging no more than 15% above the Medicare-approved amount.'),
    (v_topic_id, 'Which of the following is true regarding "Value-Based Purchasing" in Medicare?', '["It pays providers based on the volume of services", "It adjusts hospital payments based on quality and efficiency metrics", "It is a way for patients to buy cheaper drugs", "It is only for Medicaid patients"]', 1, 'Value-Based Purchasing (VBP) moves away from "fee-for-service" by rewarding providers for high-quality care and patient outcomes.'),
    (v_topic_id, 'The "Medicare Summary Notice" (MSN) is a document sent to beneficiaries that:', '["Tells them they are being audited", "Shows the services billed to Medicare and what the patient may owe", "Is a bill from the doctor", "Is a monthly premium notice"]', 1, 'The MSN is sent every 3 months and lists the services received, what Medicare paid, and the patient''s responsibility. It is not a bill.'),

    -- MISCELLANEOUS
    (v_topic_id, 'What is the "Late Enrollment Penalty" for Medicare Part B?', '["A one-time $100 fine", "A 10% increase in the premium for each 12-month period enrollment was delayed", "Loss of all Part A benefits", "A requirement to pay all back-premiums"]', 1, 'The Part B penalty is 10% for each full 12-month period a patient was eligible but didn''t sign up. This penalty is permanent.'),
    (v_topic_id, 'Which federal agency is responsible for administering the Medicare and Medicaid programs?', '["NIH", "CDC", "CMS", "FDA"]', 2, 'The Centers for Medicare & Medicaid Services (CMS) is part of the Department of Health and Human Services (HHS).'),
    (v_topic_id, 'Medicare "Part A" is technically known as:', '["Supplementary Medical Insurance (SMI)", "Hospital Insurance (HI)", "Medicare Advantage", "The Drug Benefit"]', 1, 'Part A is HI; Part B is SMI.'),
    (v_topic_id, 'Does Original Medicare have an annual "out-of-pocket maximum" (limit on how much the patient pays in a year)?', '["Yes, $2,000", "Yes, $7,550", "No", "Only for Part A"]', 2, 'Original Medicare (Parts A and B) does NOT have an annual out-of-pocket maximum. This is why many people buy Medigap or join Medicare Advantage.'),
    (v_topic_id, 'If a patient requires "custodial care" (help with ADLs like bathing/eating) in a nursing home but does NOT need skilled nursing, does Medicare pay?', '["Yes, indefinitely", "Yes, for 100 days", "No", "Only if they have Part B"]', 2, 'Medicare does not cover long-term custodial care; this is primarily covered by Medicaid (for those who qualify) or private pay.'),
    (v_topic_id, 'Which of the following describes "Balanced Billing" in the context of a doctor who does not accept assignment?', '["Charging the patient the difference between the doctor''s bill and the Medicare-approved amount", "Splitting the bill between two patients", "A way to pay for hospital construction", "The process of auditing a doctor"]', 0, 'Balanced billing is when the provider bills the patient for the remaining "balance" that Medicare didn''t pay, though it is limited by the "Limiting Charge" rule.'),
    (v_topic_id, 'A patient is admitted to the hospital for 2 days and then transferred to a SNF. Will Medicare Part A cover the SNF stay?', '["Yes", "No, because the hospital stay was less than 3 days", "Only if they have a referral", "Only if the patient is over 80"]', 1, 'The 3-day inpatient requirement is strict. Observation days do not count.'),
    (v_topic_id, 'Medicare Part B covers "screening" exams. If a screening colonoscopy reveals a polyp that is then removed, how is the visit billed?', '["It remains a $0 screening", "It becomes a "diagnostic" procedure and the patient may owe coinsurance", "Medicare pays the doctor double", "The patient gets a refund"]', 1, 'If a screening becomes diagnostic or therapeutic (e.g., biopsy/polypectomy), it is still covered, but the "waived" cost-sharing for the screening may no longer apply to the surgical portion.')
;

END $$;
COMMIT;
